def loss(w1, w2):
    return (w1 - 3) ** 2 + 2 * (w2 - 1) ** 2

print(loss(1, 3), loss(3, 1), loss(0, 0))   # 12 0 11

def loss(w1, w2):
    return (w1 - 3) ** 2 + 2 * (w2 - 1) ** 2
def grad(w1, w2):
    return [2 * (w1 - 3), 4 * (w2 - 1)]

w1, w2, lr = 1.0, 3.0, 0.1
for _ in range(100):
    g1, g2 = grad(w1, w2)
    w1, w2 = w1 - lr * g1, w2 - lr * g2
print(round(w1, 3), round(w2, 3), round(loss(w1, w2), 6))   # 3.0 1.0 0.0
